\begin{aligned}
\frac{\partial}{\partial x^{\mu'}}W_{\nu'}
&=\frac{\partial x^\mu}{\partial x^{\mu'}}
\frac{\partial}{\partial x^\mu}
\left(\frac{\partial x^\nu}{\partial x^{\nu'}}W_\nu\right)\\
&=\frac{\partial x^\mu}{\partial x^{\mu'}}
\frac{\partial x^\nu}{\partial x^{\nu'}}
\left(\frac{\partial}{\partial x^\mu}W_\nu\right)
+W_\nu\frac{\partial x^\mu}{\partial x^{\mu'}}
\frac{\partial}{\partial x^\mu}
\frac{\partial x^\nu}{\partial x^{\nu'}}.
\end{aligned}
\tag{2.38}
